import re

_UNITS = {
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "d": 86400, "day": 86400, "days": 86400,
    "w": 604800, "wk": 604800, "wks": 604800, "week": 604800, "weeks": 604800,
}

_NUM = r"\d+(?:\.\d+)?"
_COMPONENT = re.compile(r"\s*(" + _NUM + r")\s*([a-zA-Z]+)")
_ISO = re.compile(
    r"P(?:(" + _NUM + r")W)?(?:(" + _NUM + r")D)?"
    r"(?:T(?:(" + _NUM + r")H)?(?:(" + _NUM + r")M)?(?:(" + _NUM + r")S)?)?$"
)


def _finalize(total: float) -> int:
    if total < 0:
        raise ValueError("negative duration")
    return int(round(total))


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("expected a string")
    s = text.strip()
    if not s:
        raise ValueError("empty input")

    # Bare non-negative integer -> seconds
    if re.fullmatch(r"\d+", s):
        return _finalize(int(s))

    # ISO 8601 duration
    if s.startswith("P"):
        m = _ISO.fullmatch(s)
        if not m or not any(m.groups()):
            raise ValueError(f"invalid ISO duration: {text!r}")
        weeks, days, hours, mins, secs = m.groups()
        total = 0.0
        total += float(weeks or 0) * 604800
        total += float(days or 0) * 86400
        total += float(hours or 0) * 3600
        total += float(mins or 0) * 60
        total += float(secs or 0)
        return _finalize(total)

    # Clock notation hh:mm:ss or mm:ss
    if ":" in s:
        parts = s.split(":")
        if len(parts) not in (2, 3):
            raise ValueError(f"invalid clock notation: {text!r}")
        try:
            values = [float(p) for p in parts]
        except ValueError:
            raise ValueError(f"invalid clock notation: {text!r}")
        if any(v < 0 for v in values):
            raise ValueError("negative duration")
        if len(values) == 3:
            h, mi, se = values
        else:
            h, mi, se = 0, values[0], values[1]
        return _finalize(h * 3600 + mi * 60 + se)

    # number+unit components
    total = 0.0
    pos = 0
    matched = False
    while pos < len(s):
        m = _COMPONENT.match(s, pos)
        if not m or m.start() != pos:
            raise ValueError(f"invalid duration: {text!r}")
        number, unit = m.group(1), m.group(2).lower()
        if unit not in _UNITS:
            raise ValueError(f"unknown unit: {unit!r}")
        total += float(number) * _UNITS[unit]
        pos = m.end()
        matched = True
        # allow trailing spaces
        while pos < len(s) and s[pos] == " ":
            pos += 1
    if not matched:
        raise ValueError(f"invalid duration: {text!r}")
    return _finalize(total)

